content:
:root {
  --primary-color: #2563eb;
  --primary-hover: #1d4ed8;
  --bg-color: #f8fafc;
  --card-bg: #ffffff;
  --text-main: #1e293b;
  --text-sub: #64748b;
  --border-color: #cbd5e1;
  --radius: 8px;
  --shadow: 0 4px 6px -1px rgb(0 0 0 / 0.1), 0 2px 4px -2px rgb(0 0 0 / 0.1);
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif;
  background-color: var(--bg-color);
  color: var(--text-main);
  line-height: 1.5;
}

.app-container {
  max-width: 1200px;
  margin: 0 auto;
  padding: 24px 16px;
  min-height: 100vh;
  display: flex;
  flex-direction: column;
  gap: 24px;
}

.header {
  text-align: center;
  margin-bottom: 8px;
}

.header h1 {
  font-size: 2rem;
  color: var(--primary-color);
  margin-bottom: 8px;
}

.header p {
  color: var(--text-sub);
  font-size: 1rem;
}

.main-content {
  display: grid;
  grid-template-columns: 1fr;
  gap: 24px;
}

@media (min-width: 768px) {
  .main-content {
    grid-template-columns: 400px 1fr;
  }
}

.card {
  background-color: var(--card-bg);
  border-radius: var(--radius);
  box-shadow: var(--shadow);
  padding: 24px;
  display: flex;
  flex-direction: column;
  gap: 20px;
}

.form-group {
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.label {
  font-weight: 600;
  font-size: 0.95rem;
  color: var(--text-main);
}

.input {
  width: 100%;
  padding: 10px 12px;
  border: 1px solid var(--border-color);
  border-radius: var(--radius);
  font-size: 1rem;
  transition: border-color 0.2s, box-shadow 0.2s;
}

.input:focus {
  outline: none;
  border-color: var(--primary-color);
  box-shadow: 0 0 0 3px rgba(37, 99, 235, 0.15);
}

.result-box {
  display: flex;
  flex-direction: column;
  gap: 16px;
}

.summary-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(140px, 1fr));
  gap: 12px;
}

.summary-item {
  background-color: var(--bg-color);
  padding: 12px 16px;
  border-radius: var(--radius);
  border: 1px solid var(--border-color);
  display: flex;
  flex-direction: column;
  gap: 4px;
}

.summary-item .label {
  font-size: 0.8rem;
  color: var(--text-sub);
}

.summary-item .value {
  font-size: 1.1rem;
  font-weight: 700;
  color: var(--primary-color);
}

.chart-container {
  width: 100%;
  height: 320px;
  margin-top: 12px;
}

export interface LoanInput {
  amount: number;
  interestRate: number;
  years: number;
}

export interface YearlyRepayment {
  year: number;
  remainingBalance: number;
  principalPaid: number;
  interestPaid: number;
  totalPayment: number;
}

import { ChangeEvent } from 'react';
import { LoanInput } from '../types';
import '../index.css';

interface LoanFormProps {
  input: LoanInput;
  onChange: (input: LoanInput) => void;
}

export default function LoanForm({ input, onChange }: LoanFormProps) {
  const handleChange = (field: keyof LoanInput) => (e: ChangeEvent<HTMLInputElement>) => {
    const value = parseFloat(e.target.value) || 0;
    onChange({
      ...input,
      [field]: value,
    });
  };

  return (
    <div className="card">
      <div className="form-group">
        <label className="label">借入金額 (万円)</label>
        <input
          type="number"
          className="input"
          value={input.amount}
          onChange={handleChange('amount')}
          min={100}
          max={20000}
          step={100}
        />
      </div>

      <div className="form-group">
        <label className="label">金利 (%)</label>
        <input
          type="number"
          className="input"
          value={input.interestRate}
          onChange={handleChange('interestRate')}
          min={0.1}
          max={10}
          step={0.1}
        />
      </div>

      <div className="form-group">
        <label className="label">返済期間 (年)</label>
        <input
          type="number"
          className="input"
          value={input.years}
          onChange={handleChange('years')}
          min={1}
          max={50}
          step={1}
        />
      </div>
    </div>
  );
}

import { ResponsiveContainer, AreaChart, Area, XAxis, YAxis, Tooltip, Legend } from 'recharts';
import { YearlyRepayment } from '../types';
import '../index.css';

interface LoanChartProps {
  yearlyData: YearlyRepayment[];
  monthlyPayment: number;
  totalPayment: number;
  totalInterest: number;
}

export default function LoanChart({
  yearlyData = [],
  monthlyPayment = 0,
  totalPayment = 0,
  totalInterest = 0,
}: LoanChartProps) {
  const formatCurrency = (val: number) => {
    return `${Math.round(val).toLocaleString()} 円`;
  };

  const formatManYen = (val: number) => {
    return `${Math.round(val).toLocaleString()}万円`;
  };

  return (
    <div className="card">
      <div className="result-box">
        <div className="summary-grid">
          <div className="summary-item">
            <span className="label">毎月の返済額</span>
            <span className="value">{formatCurrency(monthlyPayment)}</span>
          </div>
          <div className="summary-item">
            <span className="label">総返済額</span>
            <span className="value">{formatCurrency(totalPayment)}</span>
          </div>
          <div className="summary-item">
            <span className="label">総利息額</span>
            <span className="value">{formatCurrency(totalInterest)}</span>
          </div>
        </div>

        <div className="chart-container">
          <ResponsiveContainer width="100%" height="100%">
            <AreaChart data={yearlyData} margin={{ top: 10, right: 30, left: 0, bottom: 0 }}>
              <XAxis dataKey="year" unit="年" />
              <YAxis tickFormatter={(val) => `${val}万`} />
              <Tooltip
                formatter={(value: number) => [formatManYen(value), '']}
                labelFormatter={(label) => `${label}年目`}
              />
              <Legend />
              <Area
                type="monotone"
                dataKey="remainingBalance"
                name="残高（万円）"
                stroke="#2563eb"
                fill="#3b82f6"
                fillOpacity={0.3}
              />
            </AreaChart>
          </ResponsiveContainer>
        </div>
      </div>
    </div>
  );
}

import { useState, useMemo } from 'react';
import { LoanInput, YearlyRepayment } from './types';
import LoanForm from './components/LoanForm';
import LoanChart from './components/LoanChart';
import './index.css';

export default function App() {
  const [input, setInput] = useState<LoanInput>({
    amount: 3000, // 3000万円
    interestRate: 1.2, // 1.2%
    years: 35, // 35年
  });

  const { monthlyPayment, totalPayment, totalInterest, yearlyData } = useMemo(() => {
    const principal = input.amount * 10000; // 円単位
    const monthlyRate = input.interestRate / 100 / 12;
    const totalMonths = input.years * 12;

    let monthlyPay = 0;
    if (monthlyRate === 0) {
      monthlyPay = principal / totalMonths;
    } else {
      monthlyPay =
        (principal * monthlyRate * Math.pow(1 + monthlyRate, totalMonths)) /
        (Math.pow(1 + monthlyRate, totalMonths) - 1);
    }

    const tPayment = monthlyPay * totalMonths;
    const tInterest = tPayment - principal;

    const data: YearlyRepayment[] = [];
    let balance = principal;

    for (let year = 1; year <= input.years; year++) {
      let yearlyPrincipalPaid = 0;
      let yearlyInterestPaid = 0;

      for (let m = 0; m < 12; m++) {
        const interestForMonth = balance * monthlyRate;
        const principalForMonth = monthlyPay - interestForMonth;
        yearlyInterestPaid += interestForMonth;
        yearlyPrincipalPaid += principalForMonth;
        balance -= principalForMonth;
      }

      data.push({
        year,
        remainingBalance: Math.max(0, Math.round(balance / 10000)), // 万円単位
        principalPaid: Math.round(yearlyPrincipalPaid / 10000),
        interestPaid: Math.round(yearlyInterestPaid / 10000),
        totalPayment: Math.round((yearlyPrincipalPaid + yearlyInterestPaid) / 10000),
      });
    }

    return {
      monthlyPayment: Math.round(monthlyPay),
      totalPayment: Math.round(tPayment),
      totalInterest: Math.round(tInterest),
      yearlyData: data,
    };
  }, [input]);

  return (
    <div className="app-container">
      <header className="header">
        <h1>住宅ローンシミュレーター</h1>
        <p>借入額、金利、返済期間を入力して毎月の返済額と推移を確認できます。</p>
      </header>

      <main className="main-content">
        <LoanForm input={input} onChange={setInput} />
        <LoanChart
          yearlyData={yearlyData}
          monthlyPayment={monthlyPayment}
          totalPayment={totalPayment}
          totalInterest={totalInterest}
        />
      </main>
    </div>
  );
}
